#include <vector>
#include <algorithm>

int main() {
    std::vector<int> v = {1, 2, 3, 4, 5};

    // O(N) operation: must shift 4, 5
    auto it = v.begin() + 3; // Points to 4
    v.insert(it, 99);

    // O(N) worst case: must shift all N elements
    v.insert(v.begin(), 0);

    // v is now {0, 1, 2, 3, 99, 4, 5}

    // Note: If reallocation occurs during insert, all existing iterators are invalidated.
}
